+    private long retryMillis = 250;
+
+    private ResultWaiter(ExceptionalSupplier<T> resultSupplier, Predicate<T> resultMatcher)
+    {
+      this.resultSupplier = resultSupplier;
+      this.resultMatcher = resultMatcher;
+    }
+
