+      final Stopwatch stopwatch = Stopwatch.createStarted();
+
+      try {
+        T t = resultSupplier.get();
+        boolean matches;
+        while (!(matches = resultMatcher.test(t)) && stopwatch.millisElapsed() < timeoutMillis) {
+          Thread.sleep(retryMillis);
+          t = resultSupplier.get();
+        }
