+    // Continue returning updated nodes
+    EasyMock.expect(mockConsulApiClient.watchServices(
+        EasyMock.eq(NodeRole.BROKER),
+        EasyMock.eq(1L),
+        EasyMock.anyLong()
+    ))
+            .andReturn(new ConsulApiClient.ConsulWatchResult(updatedNodes, 1L))
+            .anyTimes();
