+  @Test
+  public void test_killUnreferencedCompactionState_validateLifecycleOfActiveCompactionState()
+  {
+    // Setup time progression: now, +1hr, +7hrs
+    List<DateTime> dateTimes = new ArrayList<>();
+    DateTime now = DateTimes.nowUtc();
+    dateTimes.add(now);
