+    }
+
+    DirectoryReader reader = w.getReader();
+    IndexSearcher searcher = newSearcher(reader);
+    BooleanQuery bq =
+        new BooleanQuery.Builder()
+            .add(
+                new BoostQuery(new TermQuery(new Term("text", "aaaa")), 2.0f),
+                BooleanClause.Occur.SHOULD)
