+// EXAMPLE CODE FOR DOT PRODUCT IMPLEMENTATION IN C (Scalar, NEON, SVE)
+
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#if defined(__aarch64__) && defined(__linux__)
+#include <sys/auxv.h>
+#include <asm/hwcap.h>
