+    acc1 = vaddq_s32(acc1, acc2);
+    acc3 = vaddq_s32(acc3, acc4);
+    acc1 = vaddq_s32(acc1, acc3);
+
+    // REDUCE:  Add every vector element in target and write result to scalar
+    result += vaddvq_s32(acc1);
+    // Scalar tail
+    for (; i < limit; i++) {
+        result += vec1[i] * vec2[i];
+    }
+    return result;
