+#endif
+#endif
+
+int32_t vdot8s_scalar(int8_t vec1[], int8_t vec2[], int32_t limit) {
+    int32_t result = 0;
+    #ifdef __clang__
+    #pragma clang loop vectorize(assume_safety) unroll(enable)
+    #endif
+    for (int32_t i = 0; i < limit; i++) {
+        result += vec1[i] * vec2[i];
+    }
+    return result;
