+  test_basic_integer();
+  test_multiple_integers();
+  test_unsigned_integers();
+  test_floating_point();
+  test_float_type();
+  test_long_double_type();
+  test_mixed_floating_types();
+  test_strings();
+  test_pointers();
+  test_booleans();
+  test_characters();
+  test_mixed_types();
+  test_zero_arguments();
+  test_buffer_size_query();
+  test_long_strings();
+  test_multiple_calls();
+
+  printf("\n=== All tests passed! ===\n");
+  return 0;
+}

