+                // Stop at newline - end of current line
+                if (nodeText.getTextElement(i).isNewline()) {
+                    break;
+                }
+
+                // Stop at non-whitespace - end of whitespace sequence
+                if (!nodeText.getTextElement(i).isSpaceOrTab()) {
+                    break;
+                }
