+
+    @Test
+    void orWithNoSuppliers() {
+        Optional<String> result = Optionals.or();
+
+        assertFalse(result.isPresent());
+    }
+
+    // =========================================================================
+    // or() method tests - Lazy evaluation (short-circuit)
+    // =========================================================================
+
+    @Test
