+            $tokensJson = json_encode(\SplFixedArray::fromArray($tokens), \JSON_THROW_ON_ERROR | \JSON_PRETTY_PRINT | \JSON_NUMERIC_CHECK);
+        }
+
+        if (self::FORMAT_DUMP === $format) {
+            $output->writeln(var_export($tokens, true));
+        } else {
+            $output->writeln($tokensJson);
+        }
+
+        return 0;
+    }
+}

