+    public static function provideFixCases(): iterable
+    {
+        yield 'normal properties' => [
+            <<<'PHP'
+                <?php
+                readonly class C1
+                {
+                    private int $bar;
+                    private int $baz;
+                }
+
+                class C2
+                {
+                    private readonly int $bar;
+                    private readonly int $baz;
+                }
+                PHP,
+            <<<'PHP'
+                <?php
+                readonly class C1
+                {
+                    private readonly int $bar;
+                    private readonly int $baz;
+                }
+
+                class C2
+                {
+                    private readonly int $bar;
+                    private readonly int $baz;
+                }
+                PHP,
+        ];
+
+        yield 'promoted properties' => [
+            <<<'PHP'
+                <?php
+                readonly class C1
+                {
+                    public function __construct(
+                        private int $bar,
+                        private int $baz,
+                    ) {
+                    }
+                }
+
+                class C2
+                {
+                    public function __construct(
+                        private readonly int $bar,
+                        private readonly int $baz,
+                    ) {
+                    }
+                }
+                PHP,
+            <<<'PHP'
+                <?php
+                readonly class C1
+                {
+                    public function __construct(
+                        private readonly int $bar,
+                        private readonly int $baz,
+                    ) {
+                    }
+                }
+
+                class C2
+                {
+                    public function __construct(
+                        private readonly int $bar,
+                        private readonly int $baz,
+                    ) {
+                    }
+                }
+                PHP,
+        ];
+    }
+}

