+	// Add seed corpus from built-in test expressions
+	corpus, err := GetCorpusForFuzzParseExpr()
+	if err != nil {
+		f.Fatal(err)
+	}
+	if len(corpus) < 1000 {
+		f.Fatalf("loading exprs is likely broken: got %d expressions, expected at least 1000", len(corpus))
