+/********** Inline functions **********/
+
+static inline void keyMetaResetValues(kvobj *kv) {
+    if (unlikely(kv->metabits & KEY_META_MASK_MODULES))
+        keyMetaResetModuleValues(kv);
+    /* Must be first meta (optimized) */
+    if (kv->metabits & KEY_META_MASK_EXPIRE)
+        ((uint64_t *)kv)[-1] = -1;
