-            .metadata()
-            .cloned()
-            .or_else(|| path.p_buf.symlink_metadata().ok());
+        value.to_string()
+    }
+}
+
+fn indicator_value_is_disabled(indicator: Indicator, value: &str) -> bool {
+    if value.is_empty() {
+        !matches!(
+            indicator,
+            Indicator::OrphanedSymbolicLink | Indicator::MissingFile
+        )
+    } else {
+        value.chars().all(|c| c == '0')
+    }
+}
