+        b'\x08' => buf.push_str("\\b"),
+        b'\t' => buf.push_str("\\t"),
+        b'\n' => buf.push_str("\\n"),
+        b'\x0b' => buf.push_str("\\v"),
+        b'\x0c' => buf.push_str("\\f"),
+        b'\r' => buf.push_str("\\r"),
+        b'\x1b' => buf.push_str("\\e"),
+        b'"' => buf.push('"'),
+        b'\'' => buf.push('\''),
+        b if (0x20..=0x7e).contains(&b) => buf.push(b as char),
+        _ => {
+            let _ = write!(buf, "\\{byte:03o}");
+        }
